//! chida-db: the data layer of a Chida project.
//!
//! A [`Database`] is a set of [`Table`] definitions with typed columns,
//! validation rules and relations. The same model drives three things:
//! SQLite DDL generation, an in-memory [`Store`] used by previews and
//! logic flows, and the CRUD code generated by chida-codegen. Keeping the
//! model in pure Rust data structures means projects never depend on a
//! live database server while being designed.

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};
use std::collections::BTreeMap;
use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ColumnType {
    Text,
    Integer,
    Real,
    Money,
    Boolean,
    Date,
    DateTime,
    Image,
    File,
    Json,
    Relation,
}
impl ColumnType {
    pub fn sql_type(&self) -> &'static str {
        match self {
            Self::Text | Self::Date | Self::DateTime | Self::Image | Self::File => "TEXT",
            Self::Integer | Self::Boolean | Self::Money | Self::Relation => "INTEGER",
            Self::Real => "REAL",
            Self::Json => "TEXT",
        }
    }
    /// Rust type used in generated code.
    pub fn rust_type(&self) -> &'static str {
        match self {
            Self::Text | Self::Date | Self::DateTime | Self::Image | Self::File | Self::Json => {
                "String"
            }
            Self::Integer | Self::Relation => "i64",
            Self::Real | Self::Money => "f64",
            Self::Boolean => "bool",
        }
    }
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct Validation {
    #[serde(default)]
    pub required: bool,
    #[serde(default)]
    pub unique: bool,
    #[serde(default)]
    pub min_len: Option<usize>,
    #[serde(default)]
    pub max_len: Option<usize>,
    #[serde(default)]
    pub min: Option<f64>,
    #[serde(default)]
    pub max: Option<f64>,
    /// Value must contain this substring (a deliberately small rule set
    /// that maps cleanly to checks in generated code).
    #[serde(default)]
    pub contains: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Column {
    pub name: String,
    #[serde(rename = "type")]
    pub col_type: ColumnType,
    #[serde(default)]
    pub validation: Validation,
    #[serde(default)]
    pub default: Option<Value>,
    /// For Relation columns: the table this column points at.
    #[serde(default)]
    pub relation_table: Option<String>,
}
impl Column {
    pub fn new(name: impl Into<String>, col_type: ColumnType) -> Self {
        Self {
            name: name.into(),
            col_type,
            validation: Validation::default(),
            default: None,
            relation_table: None,
        }
    }
    pub fn required(mut self) -> Self {
        self.validation.required = true;
        self
    }
    pub fn unique(mut self) -> Self {
        self.validation.unique = true;
        self
    }
    pub fn relates_to(mut self, table: impl Into<String>) -> Self {
        self.relation_table = Some(table.into());
        self
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RelationKind {
    OneToMany,
    ManyToMany,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Relation {
    pub name: String,
    pub from_table: String,
    pub from_column: String,
    pub to_table: String,
    pub to_column: String,
    pub kind: RelationKind,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Table {
    pub name: String,
    #[serde(default)]
    pub label: String,
    pub columns: Vec<Column>,
    #[serde(default)]
    pub seed_rows: Vec<Map<String, Value>>,
}
impl Table {
    pub fn new(name: impl Into<String>) -> Self {
        let n = name.into();
        Self {
            label: n.clone(),
            name: n,
            columns: Vec::new(),
            seed_rows: Vec::new(),
        }
    }
    pub fn column(mut self, c: Column) -> Self {
        self.columns.push(c);
        self
    }
    pub fn column_named(&self, name: &str) -> Option<&Column> {
        self.columns.iter().find(|c| c.name == name)
    }
    /// CREATE TABLE statement in SQLite dialect. Every table gets an
    /// `id INTEGER PRIMARY KEY AUTOINCREMENT` unless it defines its own id.
    pub fn create_sql(&self) -> String {
        let mut cols: Vec<String> = Vec::new();
        if self.column_named("id").is_none() {
            cols.push("\"id\" INTEGER PRIMARY KEY AUTOINCREMENT".into());
        }
        for c in &self.columns {
            let mut s = format!("\"{}\" {}", c.name, c.col_type.sql_type());
            if c.name == "id" {
                s.push_str(" PRIMARY KEY AUTOINCREMENT");
            }
            if c.validation.required {
                s.push_str(" NOT NULL");
            }
            if c.validation.unique {
                s.push_str(" UNIQUE");
            }
            if let Some(t) = &c.relation_table {
                s.push_str(&format!(
                    ", FOREIGN KEY (\"{}\") REFERENCES \"{}\"(\"id\")",
                    c.name, t
                ));
            }
            cols.push(s);
        }
        format!(
            "CREATE TABLE IF NOT EXISTS \"{}\" (\n  {}\n);",
            self.name,
            cols.join(",\n  ")
        )
    }
    pub fn insert_sql(&self) -> String {
        let names: Vec<String> = self
            .columns
            .iter()
            .filter(|c| c.name != "id")
            .map(|c| format!("\"{}\"", c.name))
            .collect();
        let marks: Vec<String> = names.iter().map(|_| "?".to_string()).collect();
        format!(
            "INSERT INTO \"{}\" ({}) VALUES ({});",
            self.name,
            names.join(", "),
            marks.join(", ")
        )
    }
    pub fn select_sql(&self) -> String {
        format!("SELECT * FROM \"{}\" ORDER BY \"id\";", self.name)
    }
    /// Validate one row against column rules. Returns human readable issues.
    pub fn validate_row(&self, row: &Map<String, Value>) -> Vec<String> {
        let mut issues = Vec::new();
        for c in &self.columns {
            let v = row.get(&c.name);
            match v {
                None | Some(Value::Null) => {
                    if c.validation.required {
                        issues.push(format!("{}.{} is required", self.name, c.name));
                    }
                }
                Some(val) => {
                    if let Some(s) = val.as_str() {
                        if let Some(m) = c.validation.min_len {
                            if s.chars().count() < m {
                                issues.push(format!(
                                    "{}.{} is shorter than {m} characters",
                                    self.name, c.name
                                ));
                            }
                        }
                        if let Some(m) = c.validation.max_len {
                            if s.chars().count() > m {
                                issues.push(format!(
                                    "{}.{} is longer than {m} characters",
                                    self.name, c.name
                                ));
                            }
                        }
                        if let Some(sub) = &c.validation.contains {
                            if !s.contains(sub.as_str()) {
                                issues
                                    .push(format!("{}.{} must contain '{sub}'", self.name, c.name));
                            }
                        }
                    }
                    if let Some(n) = val.as_f64() {
                        if let Some(m) = c.validation.min {
                            if n < m {
                                issues.push(format!(
                                    "{}.{} is below the minimum {m}",
                                    self.name, c.name
                                ));
                            }
                        }
                        if let Some(m) = c.validation.max {
                            if n > m {
                                issues.push(format!(
                                    "{}.{} is above the maximum {m}",
                                    self.name, c.name
                                ));
                            }
                        }
                    }
                    let type_ok = matches!((c.col_type, val),
                    (ColumnType::Integer, Value::Number(n)) if n.is_i64() || n.is_u64()
                    ) || matches!(c.col_type, ColumnType::Text | ColumnType::Date | ColumnType::DateTime | ColumnType::Image | ColumnType::File if val.is_string())
                        || matches!(c.col_type, ColumnType::Real | ColumnType::Money if val.is_number())
                        || matches!(c.col_type, ColumnType::Boolean if val.is_boolean())
                        || matches!(c.col_type, ColumnType::Relation if val.is_number())
                        || matches!(c.col_type, ColumnType::Json);
                    if !type_ok {
                        issues.push(format!("{}.{} has the wrong type", self.name, c.name));
                    }
                }
            }
        }
        issues
    }
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct Database {
    pub tables: Vec<Table>,
    #[serde(default)]
    pub relations: Vec<Relation>,
}
impl Database {
    pub fn table(&self, name: &str) -> Option<&Table> {
        self.tables.iter().find(|t| t.name == name)
    }
    pub fn schema_sql(&self) -> String {
        self.tables
            .iter()
            .map(|t| t.create_sql())
            .collect::<Vec<_>>()
            .join("\n\n")
    }
    /// A simple migration: ALTER statements for columns present in `self`
    /// but missing in `older`, for tables that exist in both.
    pub fn migration_sql_from(&self, older: &Database) -> Vec<String> {
        let mut out = Vec::new();
        for t in &self.tables {
            if let Some(old) = older.table(&t.name) {
                for c in &t.columns {
                    if old.column_named(&c.name).is_none() {
                        out.push(format!(
                            "ALTER TABLE \"{}\" ADD COLUMN \"{}\" {};",
                            t.name,
                            c.name,
                            c.col_type.sql_type()
                        ));
                    }
                }
            } else {
                out.push(t.create_sql());
            }
        }
        out
    }
    pub fn validate(&self) -> Vec<String> {
        let mut issues = Vec::new();
        for t in &self.tables {
            if t.columns.is_empty() {
                issues.push(format!("table {} has no columns", t.name));
            }
            for c in &t.columns {
                if let Some(rt) = &c.relation_table {
                    if self.table(rt).is_none() {
                        issues.push(format!(
                            "{}.{} points at missing table {rt}",
                            t.name, c.name
                        ));
                    }
                }
            }
        }
        for r in &self.relations {
            if self.table(&r.from_table).is_none() {
                issues.push(format!(
                    "relation {} starts at missing table {}",
                    r.name, r.from_table
                ));
            }
            if self.table(&r.to_table).is_none() {
                issues.push(format!(
                    "relation {} ends at missing table {}",
                    r.name, r.to_table
                ));
            }
        }
        issues
    }
}

/// In-memory row store used by previews, logic flows and tests.
#[derive(Debug, Clone, Default)]
pub struct Store {
    pub db: Database,
    rows: BTreeMap<String, Vec<Map<String, Value>>>,
    next_id: BTreeMap<String, i64>,
}
impl Store {
    pub fn new(db: Database) -> Self {
        let mut s = Self {
            db,
            rows: BTreeMap::new(),
            next_id: BTreeMap::new(),
        };
        s.seed();
        s
    }
    fn seed(&mut self) {
        let seeds: Vec<(String, Vec<Map<String, Value>>)> = self
            .db
            .tables
            .iter()
            .map(|t| (t.name.clone(), t.seed_rows.clone()))
            .collect();
        for (name, rows) in seeds {
            for row in rows {
                let _ = self.insert(&name, row);
            }
        }
    }
    pub fn insert(&mut self, table: &str, mut row: Map<String, Value>) -> Result<i64, DbError> {
        let t = self
            .db
            .table(table)
            .ok_or_else(|| DbError::NoTable(table.into()))?
            .clone();
        let issues = t.validate_row(&row);
        if !issues.is_empty() {
            return Err(DbError::Validation(issues));
        }
        for c in &t.columns {
            if c.validation.unique {
                if let Some(v) = row.get(&c.name) {
                    if self
                        .rows
                        .get(table)
                        .map(|rs| rs.iter().any(|r| r.get(&c.name) == Some(v)))
                        .unwrap_or(false)
                    {
                        return Err(DbError::Validation(vec![format!(
                            "{}.{} must be unique",
                            table, c.name
                        )]));
                    }
                }
            }
        }
        let id = {
            let e = self.next_id.entry(table.into()).or_insert(1);
            let id = *e;
            *e += 1;
            id
        };
        row.insert("id".into(), Value::from(id));
        self.rows.entry(table.into()).or_default().push(row);
        Ok(id)
    }
    pub fn all(&self, table: &str) -> Vec<Map<String, Value>> {
        self.rows.get(table).cloned().unwrap_or_default()
    }
    pub fn get(&self, table: &str, id: i64) -> Option<Map<String, Value>> {
        self.all(table)
            .into_iter()
            .find(|r| r.get("id").and_then(|v| v.as_i64()) == Some(id))
    }
    pub fn update(
        &mut self,
        table: &str,
        id: i64,
        patch: Map<String, Value>,
    ) -> Result<(), DbError> {
        let rows = self
            .rows
            .get_mut(table)
            .ok_or_else(|| DbError::NoTable(table.into()))?;
        let row = rows
            .iter_mut()
            .find(|r| r.get("id").and_then(|v| v.as_i64()) == Some(id))
            .ok_or_else(|| DbError::NoRow(table.into(), id))?;
        for (k, v) in patch {
            if k != "id" {
                row.insert(k, v);
            }
        }
        Ok(())
    }
    pub fn delete(&mut self, table: &str, id: i64) -> bool {
        if let Some(rows) = self.rows.get_mut(table) {
            let before = rows.len();
            rows.retain(|r| r.get("id").and_then(|v| v.as_i64()) != Some(id));
            rows.len() != before
        } else {
            false
        }
    }
    pub fn count(&self, table: &str) -> usize {
        self.rows.get(table).map(|r| r.len()).unwrap_or(0)
    }
    pub fn find_by(&self, table: &str, column: &str, value: &Value) -> Vec<Map<String, Value>> {
        self.all(table)
            .into_iter()
            .filter(|r| r.get(column) == Some(value))
            .collect()
    }
}

#[derive(Debug)]
pub enum DbError {
    NoTable(String),
    NoRow(String, i64),
    Validation(Vec<String>),
}
impl fmt::Display for DbError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NoTable(t) => write!(f, "no such table: {t}"),
            Self::NoRow(t, id) => write!(f, "no row {id} in {t}"),
            Self::Validation(v) => write!(f, "validation failed: {}", v.join("; ")),
        }
    }
}
impl std::error::Error for DbError {}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    pub fn shop_db() -> Database {
        let mut products = Table::new("products")
            .column(Column::new("name", ColumnType::Text).required())
            .column(Column::new("price", ColumnType::Money).required())
            .column(Column::new("stock", ColumnType::Integer));
        products.seed_rows.push({
            let mut m = Map::new();
            m.insert("name".into(), json!("Fern"));
            m.insert("price".into(), json!(250000));
            m.insert("stock".into(), json!(8));
            m
        });
        let orders = Table::new("orders")
            .column(
                Column::new("product_id", ColumnType::Relation)
                    .required()
                    .relates_to("products"),
            )
            .column(Column::new("qty", ColumnType::Integer).required());
        Database {
            tables: vec![products, orders],
            relations: vec![Relation {
                name: "order_product".into(),
                from_table: "orders".into(),
                from_column: "product_id".into(),
                to_table: "products".into(),
                to_column: "id".into(),
                kind: RelationKind::OneToMany,
            }],
        }
    }
    #[test]
    fn create_sql_has_keys_and_fk() {
        let db = shop_db();
        let sql = db.schema_sql();
        assert!(sql.contains("CREATE TABLE IF NOT EXISTS \"products\""));
        assert!(sql.contains("FOREIGN KEY"));
        assert!(sql.contains("AUTOINCREMENT"));
    }
    #[test]
    fn insert_select_sql() {
        let t = &shop_db().tables[0];
        assert!(t.insert_sql().contains("INSERT INTO \"products\""));
        assert!(t.select_sql().contains("SELECT * FROM \"products\""));
    }
    #[test]
    fn store_seed_insert_get_delete() {
        let mut s = Store::new(shop_db());
        assert_eq!(s.count("products"), 1);
        let mut row = Map::new();
        row.insert("name".into(), json!("Cactus"));
        row.insert("price".into(), json!(90000));
        let id = s.insert("products", row).unwrap();
        assert_eq!(s.get("products", id).unwrap()["name"], json!("Cactus"));
        assert!(s.delete("products", id));
        assert_eq!(s.count("products"), 1);
    }
    #[test]
    fn validation_required_and_unique() {
        let mut db = shop_db();
        db.tables[0].columns[0].validation.unique = true;
        let mut s = Store::new(db);
        let mut bad = Map::new();
        bad.insert("price".into(), json!(1));
        assert!(s.insert("products", bad).is_err());
        let mut dup = Map::new();
        dup.insert("name".into(), json!("Fern"));
        dup.insert("price".into(), json!(2));
        assert!(s.insert("products", dup).is_err());
    }
    #[test]
    fn relations_validate() {
        let mut db = shop_db();
        assert!(db.validate().is_empty());
        db.relations[0].to_table = "ghost".into();
        assert!(!db.validate().is_empty());
    }
    #[test]
    fn migration_adds_column() {
        let old = shop_db();
        let mut new = old.clone();
        new.tables[0]
            .columns
            .push(Column::new("sku", ColumnType::Text));
        let m = new.migration_sql_from(&old);
        assert_eq!(m.len(), 1);
        assert!(m[0].contains("ADD COLUMN \"sku\""));
    }
    #[test]
    fn find_by_works() {
        let s = Store::new(shop_db());
        assert_eq!(s.find_by("products", "name", &json!("Fern")).len(), 1);
    }
}
